		}
		plan.Reason = fmt.Sprintf("✓ Checkpoints live on %s. Nothing to do.", dest)
	case len(plan.Sources) == 0:
		// (d) Local checkpoints that never left this clone.
		plan.State = syncStatePublishOnly
