// run in parallel.
func entireStatusRepo(t *testing.T) string {
	t.Helper()
	testutil.IsolateGitConfigEnv(t)
	dir := setupTestRepo(t)
	testutil.WriteFile(t, dir, "README.md", "hello")
	testutil.GitAdd(t, dir, "README.md")
	testutil.GitCommit(t, dir, "initial")
